insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('111277eb-652c-4e7b-a474-8be535e21b1a'::uuid,'en','gieokui-seupjak-a-study-of-memory','Gieokui Seupjak (A Study of Memory)','Gieokui Seupjak is a much-loved 1994 ballad by the duo Jeollamhoe, featuring Kim Dong-ryul.','Kim Dong-ryul and Seo Dong-wook won the grand prize at the 1993 MBC College Music Festival as the duo Jeollamhoe, and released "Gieokui Seupjak" the following year on their debut album Exhibition. At a time when dance and reggae dominated the charts, its lyrical ballad style won over listeners with Kim''s delicate composition. The song saw a second wave of popularity after being featured in the 2012 film Architecture 101, climbing back up the charts and cementing its place as a classic of Korean balladry across generations.','Kim Dong-ryul and Seo Dong-wook debuted as the duo Jeollamhoe after winning the grand prize and a special award at the December 1993 MBC College Music Festival. In 1994 they released their debut album Exhibition, produced with contributions from Shin Hae-chul and Kim Hyung-suk, with "Gieokui Seupjak" as its opening track. Written, composed, and arranged entirely by Kim Dong-ryul, the song was well received on release, then re-entered the charts after being used in the 2012 film Architecture 101, becoming a cross-generational staple of Korean ballads.','Cited as a landmark example when discussing classic 1990s ballads.',NULL,array['기억의 습작','Jeollamhoe Gieokui Seupjak','A Study of Memory'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('1849c6f7-e13a-49a1-89a6-a13c87ec42d5'::uuid,'en','choi-dong-won-sun-dong-yol-iron-arm-rivalry','Choi Dong-won vs. Sun Dong-yol: The Iron Arm Rivalry','A legendary 1987 pitching duel between Choi Dong-won and Sun Dong-yol that ended in a 15-inning complete-game draw, still regarded as the greatest rivalry in KBO history.','On May 16, 1987, at Sajik Stadium in Busan, Lotte''s Choi Dong-won and Haitai''s Sun Dong-yol each pitched a full 15 innings, throwing 209 and 232 pitches respectively, in a game that ended 2-2. The two aces had already split two previous head-to-head starts before this game. The rivalry resurfaced in 2022 when Sun Dong-yol and Choi Dong-won placed first and second in a fan vote for the KBO''s 40 Legends, marking the league''s 40th anniversary.','The May 16, 1987 Lotte-Haitai game; revisited during the KBO''s 40th-anniversary Legends vote in 2022.','Cited as the quintessential KBO legend when discussing the greatest pitching duels in Korean baseball history.',NULL,array['최동원-선동열 무쇠팔 라이벌전','Choi Dong-won Iron Arm','Sun Dong-yol vs Choi Dong-won draw'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('1866f498-f749-41b1-98f4-de2d1723f95a'::uuid,'en','qualifications-of-men-youth-choir-nella-fantasia','Qualifications of Men: Youth Choir''s "Nella Fantasia"','A choir special on the KBS variety show Qualifications of Men that followed up its ''Nella Fantasia'' sensation with an all-senior-citizen ''Youth Choir.''','KBS''s Qualifications of Men (2009-2013) sparked a sensation with its ''Harmony'' choir special performing ''Nella Fantasia,'' and later produced a follow-up special, the ''Youth Choir,'' made up entirely of elderly members. Conductor Park Kalin drew attention for her charismatic direction, and when the Youth Choir segment ended in late October 2011, writer Lee Woo-jung left the show.','Spun off from KBS Qualifications of Men''s ''Harmony'' special; the Youth Choir arc ended in 2011.','Referenced as the originator of the heartwarming choir-variety-show format.',NULL,array['남자의 자격 청춘합창단 넬라 판타지아','남격 합창단','청춘합창단','Namgyeok Choir','Youth Choir'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('1f6a0eef-6fe0-4508-a3ab-8abe3ced086a'::uuid,'en','hiddink-i-am-still-hungry','Hiddink: "I Am Still Hungry"','Guus Hiddink''s famous line of humility after leading South Korea to its first-ever World Cup round of 16 in 2002.','When the South Korean national team reached the Round of 16 for the first time at the 2002 World Cup and players were tempted to be satisfied, coach Guus Hiddink told them, "I am still hungry." The line became a widely used quote across many fields, invoked whenever someone wants to say they won''t settle and will keep pushing toward a bigger goal.','A remark by South Korea national team head coach Guus Hiddink during the 2002 FIFA World Cup Korea/Japan.','Quoted to emphasize humility and continued effort after achieving a goal.',NULL,array['히딩크 "나는 아직 배가 고프다"','아직 배고프다','히딩크 어록','I''m still hungry','Hiddink quote'],'[{"text": "Reached the goal, but I am still hungry.", "situation": "KakaoTalk"}, {"text": "This mindset is totally Hiddink-style.", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('2c7e2c44-0937-47f3-ade4-af273ce4a49e'::uuid,'en','professor-jeong-il-yeong-rhetoric-meme','Professor Jeong Il-yeong''s Rhetoric Meme','A distinctive way of handling confrontation, taught by an Inha University French lecturer on Chimchakman''s show, that turned into a meme.','Jeong Il-yeong, a French-language lecturer at Inha University, appeared on comedian Chimchakman''s YouTube channel during the 2024 Paris Olympics season and explained, in his own distinctive style, how to respond to situations such as being caught riding the subway without a ticket or facing unfair treatment in France. Phrases like "We are customers who do XX" and "Tell the patron to come out!" became memes that viewers applied to all kinds of situations.','An appearance on Chimchakman''s YouTube channel during the 2024 Paris Olympics season.','Quoted to describe confidently standing up to unfair treatment.','The meme was later distorted and spread with inaccurate claims (e.g., about military service), prompting a correction report.',array['정일영 선생님 화법 밈','정일영 선생님','Professor Jeong Il-yeong'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('436ddcf5-5521-49ad-9a1c-32fb14ce0393'::uuid,'en','lee-malnyeon-series','Lee Malnyeon Series','A gloriously absurd webtoon by cartoonist Lee Malnyeon, who debuted in 2009 after building a following on DC Inside.','Lee Malnyeon, an amateur cartoonist active on the online community DC Inside, gained attention with works like "The Bus Is on Fire" before officially debuting his webtoon Lee Malnyeon Series in 2009. Known for plots that abandon logical coherence in favor of absurd, deliberately nonsensical ("byeongmat") humor, the series became a defining example of the byeongmat webtoon genre.','Debuted as an official webtoon after Lee Malnyeon''s amateur comics on DC Inside.','Cited as the originating example of byeongmat (deliberately absurd) webtoons.',NULL,array['이말년 씨리즈','이말년씨리즈','Lee Malnyeon Comics'],'[{"text": "This plot twist is straight-up Lee Malnyeon Series-level absurd.", "situation": "KakaoTalk"}, {"text": "Lee Malnyeon started the whole absurdist webtoon genre.", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('47150dcf-062e-422a-b52e-71913716e2ac'::uuid,'en','it-tasted-like-persimmon-so-i-thought-it-was-persimmon','"It Tasted Like Persimmon, So I Thought It Was Persimmon"','A viral circular-logic catchphrase from the 2003 Korean historical drama Jewel in the Palace, spoken by the child version of the lead character.','In the MBC drama Jewel in the Palace, the young Jang-geum describes the taste of a dish as persimmon, and when the head court lady presses her on how she knows, she circularly answers that she thought it was persimmon because it tasted like persimmon. The scene became so widely parodied that the line seemed to turn up on TV constantly.','A line from episode 5 of MBC''s Jewel in the Palace, broadcast September 29, 2003.','Quoted playfully to point out an answer that is circular or doesn''t actually explain anything.',NULL,array['홍시맛이 나서 홍시라 생각했는데','홍시맛이 나서 홍시라 생각한 것이온데','Jewel in the Palace persimmon line'],'[{"text": "So why did you do that... ''it tasted like persimmon so I thought it was persimmon'' lol", "situation": "KakaoTalk"}, {"text": "This answer is totally circular logic.", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('47a82b00-1c73-4829-ba79-3c6b2ac305be'::uuid,'en','pc-communication-modem-dial-up-sound','PC Communication Modem Dial-up Sound','The screeching dial-up modem connection sound that symbolizes 1990s Korean PC communication and early internet culture.','The distinctive dial-up modem connection sound, a screeching, crackling sequence often described as ''beep, static, hiss,'' that played when connecting to 1990s PC communication services like Hitel and Nownuri remains a powerful nostalgic symbol for that generation of early internet users. It wasn''t uncommon for the connection to drop if someone picked up the phone.','The dial-up modem handshake tone heard through the phone line when connecting to PC communication services such as Hitel, Chollian, and Nownuri in the early-to-mid 1990s. The sound was produced during the handshake process used to exchange digital signals over a phone line, and users of the era often jokingly compared it to a toilet flushing or a scream, turning it into an early meme. It disappeared with the rollout of broadband internet, but sampled audio clips and nostalgic YouTube videos keep it alive as a cultural symbol for those who grew up in the 1980s-90s.','Can be recalled by imitating the sound when reminiscing about the PC communication era.',NULL,array['PC통신 모뎀 접속음','모뎀 접속 소리','삐- 치이이','Modem connection sound'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7cc58443-34af-46ea-b6ce-7d2dd54c8ffd'::uuid,'en','look-eo-looksam-speak','Look-eo (Looksam-speak)','A set of slang terms coined from the streamer Looksam''s distinctively slurred pronunciation on Chzzk.','"Look-eo" refers to the slang vocabulary that grew out of the unique, slurred pronunciation of Looksam, a Chzzk streamer and former Hearthstone pro gamer. The slang spread rapidly in early September 2025 during a wave of collaborative Dead by Daylight streams with other creators. When a new term emerges that even Looksam himself doesn''t recognize, fans name it after whoever coined it, calling it an "X-turi."','Slang coined by viewers from Chzzk streamer Looksam''s pronunciation quirks.','Slang used among Chzzk viewers of Looksam''s streams; hard to understand without the context.','As fandom-specific slang, meaning may not carry over to general use.',array['룩어','Looker','룩삼어','Look-eo'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7e246da6-a151-4445-bc0d-dd88b18cfc6b'::uuid,'en','sorry-for-being-cute-kawaikute-gomen','"Sorry for Being Cute" (Kawaikute Gomen)','A dance challenge, set to a song by the Japanese unit HoneyWorks, featuring blown kisses and an apologetic hand-to-cheek gesture.','After the music video for HoneyWorks'' character song "Kawaikute Gomen" ("Sorry for Being Cute") was released in November 2022, a dance challenge built around its blow-kiss and apologetic cheek-touch gestures took off on TikTok. A fan-made version had already started circulating in August 2022, and by December that year K-pop idols were posting their own versions, spreading the trend both in Korea and abroad.','Release of the music video for HoneyWorks'' song "Kawaikute Gomen" (November 2022).','A short, cute dance challenge that''s easy for anyone to copy.',NULL,array['귀여워서 미안해','可愛くてごめん','Kawaikute Gomen'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8b03db9e-2152-4fdb-a21c-77398d5c998f'::uuid,'en','launch-of-ongamenet-starleague','The Launch of OnGameNet StarLeague','The 1999-2000 origin point of Korea''s professional esports league culture.','Starting with the ''99 PKO tournament in 1999 and officially adopting the name "StarLeague" from the 2000 Freechal-sponsored season, OnGameNet StarLeague became the starting point of Korea''s esports spectator culture, introducing open studio sets and live audience seating.','Korea''s esports league culture began with the ''99 PKO tournament in 1999, and the name "StarLeague" was first used for the 2000 Hanaro Telecom Tooniverse StarLeague. Riding that tournament''s popularity, the dedicated gaming channel OnGameNet launched on July 24, 2000 at the proposal of Hwang Hyung-jun, growing from a handful of contract staff broadcasting out of a converted storage room into a full broadcaster with roughly 80 employees. Around the same time, in February 2000, the Minister of Culture and Tourism used the term "e-sports" at the founding ceremony of the 21st Century Pro-Gamers Association (now the Korea e-Sports Association), helping popularize the term.','Cited as the starting point of Korea''s esports industry.',NULL,array['온게임넷 스타리그 출범','스타리그','99 PKO','StarLeague','OGN StarLeague'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('984b4bc5-357d-4334-8632-0086d6697368'::uuid,'en','youve-worked-hard-now-go','"You''ve Worked Hard, Now Go"','A 2001 Hyundai Card ad tagline that became a byword for encouraging people to take a vacation.','The tagline "You''ve worked hard, now go," from a 2001 Hyundai Card commercial starring Jung Joon-ho and Jang Jin-young, became a common expression for urging someone to take a trip or vacation. It continued to be referenced and parodied in travel-related copy long after the ad aired.','A tagline from a Hyundai Card TV commercial contrasting actors Jung Joon-ho and Jang Jin-young sweating through hard work with a scene of them heading off into nature, set to Simon & Garfunkel''s "The Boxer." The stylish, fresh visuals made the ad a sensation and turned the line into a catchphrase; during later corporate restructuring waves, it was even twisted into "You''ve worked hard, now leave (the company)." The ad is understood to have aired in 2001, though major coverage of its popularity was published in 2002.','Can be quoted directly when encouraging someone to take a vacation or trip.',NULL,array['열심히 일한 당신, 떠나라','열일당신 떠나라','현대카드 카피','Hyundai Card tagline'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9b4cc86f-09ce-475c-bb83-c1ffcbab309e'::uuid,'en','minecraft-inde-challenge','"Minecraft-inde" Challenge','A challenge inviting fans to insert their own original character into Minecraft streamer Wonda''s song "Nemo-inde."','Korean YouTuber Ibion adapted American YouTuber camman18''s "Minecraft, but" Shorts format into a series called "Minecraft-inde" ("It''s Minecraft, but..."), and on May 24, 2024, Minecraft YouTuber Wonda released the digital single "Nemo-inde" ("It''s a Cube, but...") featuring Gemmatalk and Geumsahyang. After Wonda released downloadable files that let fans insert their own original characters, many YouTubers joined the "Minecraft-inde" challenge.','YouTuber Wonda''s digital single "Nemo-inde" and its accompanying original-character asset files.','Introduced as an example of a game-YouTuber collaboration challenge.',NULL,array['마인크래프트인데 챌린지','네모인데','원다 네모인데','Nemo-inde'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9c2d304d-8053-4448-8e1f-f700c82e8e33'::uuid,'en','maekkeun-maekkeunhada-challenge','"Maekkeun-maekkeunhada" Challenge','A viral dance born from French choreographer Kani memorizing Korean adjectives on a YouTube variety show.','In episode 20 of the YouTube variety show "Finding Kani," aired October 29, 2025, French-born choreographer Kani improvised a dance while repeating Korean adjectives such as "maekkeun-maekkeunhada, maekkeun-maekkeunhan" (smooth) and "pyeongpyeonghada, pyeongpyeonghan" (flat), and the clip went viral. A remix video by Haengbokhan Pizzabbang later became popular, and idols including SHINee''s Key, TWS, Hearts2Hearts, and ZB1 joined in with their own versions; the timing overlapping with Korea''s college entrance exam season earned it the nickname "the 2025 song banned during exam prep."','The adjective-memorizing scene from episode 20 of the YouTube show "Finding Kani."','A good example to cite for an addictively catchy dance challenge.',NULL,array['매끈매끈하다 챌린지','매끈매끈한','카니를 찾아서','수능 금지곡(2025)','Finding Kani'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9d430343-4454-4433-a0f8-ca4f27395272'::uuid,'en','sky-castle-sseoaeng-nim','SKY Castle''s "Sseoaeng-nim"','A catchphrase born from actress Yeom Jung-ah''s exaggerated pronunciation of "teacher" (seonsaengnim) in the drama SKY Castle.','In the 2018 JTBC drama SKY Castle, Yeom Jung-ah''s character Han Seo-jin clings to admissions coordinator Kim Ju-young (played by Kim Seo-hyung), pronouncing "seonsaengnim" (teacher) as "sseoaeng-nim," and the scene went viral. Other lines from the show, including "eogalmeori" and "who killed Hyena," likewise became catchphrases that were widely parodied and impersonated.','A line spoken by Han Seo-jin (Yeom Jung-ah) in the JTBC drama SKY Castle (2018).','Used to parody desperately trying to persuade someone.',NULL,array['SKY 캐슬 쓰앵님','아갈머리','혜나는 누가 죽였나요','Sseoaeng-nim','Eogalmeori'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('b4354c93-bfd9-4fc3-b24b-d5e1f944b3f0'::uuid,'en','balletcore','Balletcore','A TikTok-born fashion aesthetic that blends ballet-wear silhouettes into everyday clothing.','Balletcore mixes ballet elements, leotards, wrap skirts, leg warmers, ballet flats, into casual outfits. It spread through TikTok and Instagram under the hashtag #balletcore, defined by ribbon details and soft pastel color palettes. In Korea, it became associated with Red Velvet''s "Feel My Rhythm" and NewJeans'' pictorials.','Coined in the early 2020s on TikTok and Instagram as a blend of "ballet" and "normcore"; search interest surged in Korea after Red Velvet''s comeback in late 2022.','Used to describe an elegant look styled with items like ballet flats and leg warmers.',NULL,array['발레코어','발레코어룩','balletcore','Balletcore look'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('c4647c65-bf96-4465-b0df-c9772cb03f07'::uuid,'en','park-ji-sung-two-hearts','Park Ji-sung''s "Two Hearts"','Park Ji-sung''s signature nickname, earned for his tireless work rate on the pitch.','During his time at Manchester United, Park Ji-sung earned the nickname "Two Hearts" for his overwhelming, seemingly inexhaustible work rate throughout an entire match. British media also described his stamina as "Three-Lung Park." His resting heart rate was reportedly around 40 beats per minute, cited as a textbook example of a long-conditioned athlete''s heart.','Established through his performances at Manchester United in the mid-2000s.','A signature nickname used when discussing Park Ji-sung''s exceptional work rate and stamina.',NULL,array['박지성 두 개의 심장','Three-Lung Park','Park Ji-sung Two Hearts'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('da72423d-7a4c-4f54-9e40-4eb18ea6d1bf'::uuid,'en','pick-me-naya-na-syndrome','"Pick Me" (Naya Na) Syndrome','The nationwide sensation sparked by the theme song of Produce 101 Season 2.','Mnet''s "Produce 101 Season 2," which aired from April to June 2017, sparked a nationwide sensation with its theme song "Naya Na (Pick Me)" and its trainee group choreography, dominating the music and broadcasting scene that spring. The group Wanna One, formed through the show, debuted in August 2017 to explosive popularity, and the song and its choreography became a go-to subject for parody on variety shows and at events.','The theme song of Mnet''s "Produce 101 Season 2" (2017).','Referenced as an audition-show sensation and a frequent subject of group-dance parody.',NULL,array['나야 나(PICK ME) 신드롬','워너원 나야나','국프 나야나','Wanna One Pick Me','Naya Na'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('dc46243d-f704-4519-ba01-bca3819b8be4'::uuid,'en','be-the-reds-t-shirt','"Be the Reds" T-Shirt','The red T-shirt reading "Be the Reds!" that became South Korea''s unofficial national uniform during the 2002 World Cup.','Created by the Red Devils supporters'' group with the slogan "Be the Reds!," this red T-shirt sold hundreds of thousands of units within a month of its May 2002 release, turning into a uniform worn by the entire nation. It later drew attention again in a lawsuit over the design''s copyright.','An official Red Devils supporters'' merchandise item, released in 2002 and designed by Park Young-cheol.','Can be cited as merchandise symbolizing the fervor of the 2002 World Cup.',NULL,array['Be the Reds 티셔츠','비더레즈','붉은악마 티셔츠','Red Devils T-shirt'],'[{"text": "Let''s all match in Be the Reds T-shirts for this cheer.", "situation": "KakaoTalk"}, {"text": "That was the national uniform back then.", "situation": "SNS comment"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('ddee812b-43f0-428f-b4ef-4133ff504ed8'::uuid,'en','amazon-express-ceremony','Amazon Express Ceremony','A surprise cast dance at a theme park rafting ride that was belatedly rediscovered as a viral meme.','Since 2006, cast members at Everland''s Amazon Express rafting ride have performed a surprise "Amazon welcome ceremony" dance for riders. It suddenly went viral in 2019 after being featured in web-variety shows like Workman and in videos by YouTuber Yoonzzukku. The rap was written by Yoonzzukku, while the choreography and composition were handled by lead cast member Son Yeong-hun.','The cast dance at Everland''s Amazon Express, rediscovered online in 2019.','Can be cited as an example of a fun theme-park dance routine.',NULL,array['아마존 익스프레스 세레모니','아마존 환영 세레모니','Amazon welcome ceremony'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00'::timestamptz,'claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
